/**
 * E3 (W5d / ND-7): order_number generated by the database.
 * Migration under test: 20261024100200_order_number_sequence.sql
 *   generate_order_number() = 'ORD-' || YYYYMMDD || '-' || nextval(order_sequence) with NO lpad (lpad truncates:
 *   the old LPAD(..., 4) repeated numbers from 10000 on), and the sequence never starts below 100000, so it cannot
 *   collide with the 5-digit random numbers that cached old clients still send during the deploy.
 */
import { describe, it, expect, beforeAll, afterAll, afterEach } from 'vitest';
import { readFileSync } from 'node:fs';
import { dbSuiteSkipReason, connectAdmin, connectAs, endAll } from './db';
import { loadActors, createTracker, seedOrder, cleanup } from './fixtures';

const MIGRATION = 'supabase/migrations/20261024100200_order_number_sequence.sql';

const skipReason = await dbSuiteSkipReason({ functions: ['generate_order_number', 'set_order_number'], tables: ['orders'] });
const describeDb = skipReason ? describe.skip : describe;

describe('order number migration contract (static)', () => {
  const sql = () => readFileSync(MIGRATION, 'utf8');

  it('does not pad with lpad (it truncates longer numbers)', () => {
    expect(sql()).not.toMatch(/lpad/i);
  });

  it('raises the sequence to at least 100000 and never moves it backwards', () => {
    expect(sql()).toMatch(/setval\(\s*'public\.order_sequence'/i);
    expect(sql()).toMatch(/GREATEST\(\s*100000/i);
  });
});

describeDb('generate_order_number / trigger_set_order_number', () => {
  let admin;
  let actors;
  const tracker = createTracker();
  const clients = [];

  const ownerInsert = async (client) => {
    const { rows } = await client.query(
      `INSERT INTO public.orders (user_id, order_type, subtotal, total_amount, currency_id, payment_method)
       VALUES ($1, 'product', 10, 10, $2, 'zelle') RETURNING id, order_number`,
      [actors.customerId, actors.currencyId]
    );
    tracker.orders.push(rows[0].id);
    return rows[0].order_number;
  };

  beforeAll(async () => {
    admin = await connectAdmin();
    actors = await loadActors(admin);
  });
  afterEach(async () => {
    await endAll(clients.splice(0));
    await cleanup(admin, tracker);
  });
  afterAll(async () => {
    await admin.end();
  });

  it('the sequence floor is 100000', async () => {
    const { rows } = await admin.query('SELECT last_value, is_called FROM public.order_sequence');
    expect(Number(rows[0].last_value)).toBeGreaterThanOrEqual(100000);
  });

  it('formats ORD-YYYYMMDD-<n> with n of 6+ digits', async () => {
    const { rows } = await admin.query('SELECT public.generate_order_number() AS n');
    expect(rows[0].n).toMatch(/^ORD-\d{8}-\d{6,}$/);
  });

  it('does not truncate when the counter grows (lpad regression)', async () => {
    await admin.query(`SELECT setval('public.order_sequence', 1234566, true)`);
    const { rows } = await admin.query('SELECT public.generate_order_number() AS n');
    expect(rows[0].n).toMatch(/-1234567$/);
  });

  it('two concurrent owner INSERTs without order_number get different, increasing numbers', async () => {
    const a = await connectAs(actors.customerId);
    const b = await connectAs(actors.customerId);
    clients.push(a, b);
    const [n1, n2] = await Promise.all([ownerInsert(a), ownerInsert(b)]);
    expect(n1).not.toBe(n2);
    const seq = (n) => Number(n.split('-')[2]);
    expect(seq(n1)).toBeGreaterThanOrEqual(100000);
    expect(Math.abs(seq(n1) - seq(n2))).toBeGreaterThan(0);
  });

  it('guard_orders_owner_insert accepts a NULL order_number and the trigger fills it', async () => {
    const owner = await connectAs(actors.customerId);
    clients.push(owner);
    expect(await ownerInsert(owner)).toMatch(/^ORD-\d{8}-\d{6,}$/);
  });

  it('a client-supplied order_number is still honoured (old bundles keep working)', async () => {
    const id = await seedOrder(admin, actors, tracker, []);
    const { rows } = await admin.query('SELECT order_number FROM public.orders WHERE id = $1', [id]);
    expect(rows[0].order_number).toMatch(/^TST-/);
  });

  // Runs a migration/rollback file inside a transaction that is always rolled back.
  const inRolledBackTxn = async (file, before, after) => {
    const body = readFileSync(file, 'utf8').replace(/^(BEGIN|COMMIT);\s*$/gm, '');
    await admin.query('BEGIN');
    try {
      if (before) await admin.query(before);
      await admin.query(body);
      return after ? (await admin.query(after)).rows[0] : null;
    } finally {
      await admin.query('ROLLBACK');
    }
  };

  it('the rollback does not truncate once the sequence is past 4 digits (no duplicate numbers if only the SQL is reverted)', async () => {
    const row = await inRolledBackTxn(
      'supabase/rollbacks/20261024100200_order_number_sequence_down.sql',
      `SELECT setval('public.order_sequence', 123456, false)`,
      'SELECT public.generate_order_number() AS n'
    );
    expect(row.n).toMatch(/^ORD-\d{8}-123456$/);
  });

  it('the rollback keeps the old 4-digit padding while the sequence is small', async () => {
    const row = await inRolledBackTxn(
      'supabase/rollbacks/20261024100200_order_number_sequence_down.sql',
      `SELECT setval('public.order_sequence', 7, false)`,
      'SELECT public.generate_order_number() AS n'
    );
    expect(row.n).toMatch(/^ORD-\d{8}-0007$/);
  });

  it('the migration aborts with a clear message when trigger_set_order_number is missing', async () => {
    let error;
    try {
      await inRolledBackTxn(MIGRATION, 'DROP TRIGGER trigger_set_order_number ON public.orders');
    } catch (e) {
      error = e;
    }
    expect(error?.message).toMatch(/trigger_set_order_number/);
  });

  it('the migration applies cleanly when the trigger exists', async () => {
    await expect(inRolledBackTxn(MIGRATION)).resolves.toBeNull();
  });
});
